import sys,itertools,time
import os; HERE=os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0,HERE); sys.path.insert(0,os.path.join(HERE,'..','g777'))
import carrier_lib as lib
from carrier_lib import lab,lines,simple,solve,n
import numpy as np
g={0:0,1:1,2:2,3:4,4:8,5:12,6:20,7:36}
par=lambda x: bin(x).count('1')&1
# simple-root coordinates of each line
coef=[solve(simple,l) for l in lines]
coef=[[int(v) for v in c] for c in coef]
def parabolic(I):
    """set of line indices in the parabolic subsystem generated by simple roots I"""
    return [t for t in range(n) if all(coef[t][k]==0 for k in range(8) if k not in I)]
PC=np.array([bin(i).count('1') for i in range(1<<16)],dtype=np.uint8)
def pc(a):
    a=a.astype(np.uint64)
    return (PC[(a&np.uint64(0xffff)).astype(np.int64)]+PC[((a>>np.uint64(16))&np.uint64(0xffff)).astype(np.int64)]
            +PC[((a>>np.uint64(32))&np.uint64(0xffff)).astype(np.int64)]+PC[((a>>np.uint64(48))&np.uint64(0xffff)).astype(np.int64)]).astype(np.int32)
def split(m): return m&((1<<64)-1), m>>64
class Tgt:
    def __init__(s,T):
        s.T=list(T); s.k=len(s.T)
        s.Z=[0]*512
        for a in range(1,512):
            m=0
            for i,t in enumerate(s.T):
                if not par(a&lab[t]): m|=1<<i
            s.Z[a]=m
        zs=sorted(set(s.Z[1:])-{0})
        s.zlo=np.array([split(m)[0] for m in zs],dtype=np.uint64); s.zhi=np.array([split(m)[1] for m in zs],dtype=np.uint64)
        s.full=(1<<s.k)-1
        s.cache={}
    def level(s,w,L):
        key=(w,L)
        if key in s.cache: return s.cache[key]
        import subprocess
        inp="\n".join("%d %d"%split(s.Z[a]) for a in range(1,512))+"\n"
        out=subprocess.run([os.environ.get('SUBBIN',os.path.join(HERE,'sub')),str(9-w),str(L)],input=inp,capture_output=True,text=True).stdout
        res=[int(x)|(int(y)<<64) for x,y in (ln.split() for ln in out.splitlines())]
        s.cache[key]=res; return res
def bits(m):
    while m:
        b=m&-m; yield b.bit_length()-1; m^=b
def cover(tg,ws,deadline=None,stats=None):
    """can all of tg.full be covered by flats of weights ws (w=1: single line)?"""
    ws=sorted(ws,reverse=True)
    full=tg.full
    def cap(r): return sum(g[w] for w in r)
    memo=set()
    def rec(unc,rem):
        if unc==0: return True
        if bin(unc).count('1')>cap(rem): return False
        key=(unc,tuple(rem))
        if key in memo: return False
        p=(unc&-unc).bit_length()-1
        for w in sorted(set(rem),reverse=True):
            r2=list(rem); r2.remove(w)
            need=bin(unc).count('1')-cap(r2)   # this flat must cover >= need of unc
            if w==1:
                if rec(unc&~(1<<p),r2): return True
                continue
            if w==2:
                for q in bits(unc&~(1<<p)):
                    if rec(unc&~(1<<p)&~(1<<q),r2): return True
                if rec(unc&~(1<<p),r2): return True
                continue
            L=max(need,1)
            cands=[m for m in tg.level(w,max(1,1)) ] if False else tg.level(w,2)
            best=[]
            for m in cands:
                if (m>>p)&1:
                    c=bin(m&unc).count('1')
                    if c>=need: best.append((c,m))
            best.sort(reverse=True)
            for c,m in best:
                if rec(unc&~m,r2): return True
        memo.add(key); return False
    return rec(full,ws)
